-- English content library additions: 8 items, generated by scripts/english-content/build-seed.ts
-- from supabase/content/english/. Every item passed the content studio validator. Idempotent: existing slugs are skipped.
do $$
declare
  v_seed text := '20261124151000_english_hub_read_reply_speak';
  v_en_id uuid;
  v_parent_id uuid;
  v_product_reading uuid;
  v_product_listening uuid;
  v_product_writing uuid;
  v_product_speaking uuid;
  v_product_grammar uuid;
  v_product_immersion uuid;
  v_product_vocabulary uuid;
begin
  select id into v_en_id from public.languages where code = 'en' limit 1;
  if v_en_id is null then raise exception 'English language row not found'; end if;
  select p.id into v_product_reading from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-reading' order by p.created_at asc limit 1;
  if v_product_reading is null then raise exception 'english-reading product not found'; end if;
  select p.id into v_product_listening from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-listening' order by p.created_at asc limit 1;
  if v_product_listening is null then raise exception 'english-listening product not found'; end if;
  select p.id into v_product_writing from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-writing' order by p.created_at asc limit 1;
  if v_product_writing is null then raise exception 'english-writing product not found'; end if;
  select p.id into v_product_speaking from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-speaking' order by p.created_at asc limit 1;
  if v_product_speaking is null then raise exception 'english-speaking product not found'; end if;
  select p.id into v_product_grammar from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-grammar' order by p.created_at asc limit 1;
  if v_product_grammar is null then raise exception 'english-grammar product not found'; end if;
  select p.id into v_product_immersion from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-immersion' order by p.created_at asc limit 1;
  if v_product_immersion is null then raise exception 'english-immersion product not found'; end if;
  select p.id into v_product_vocabulary from public.products p
  where lower(coalesce(p.metadata->>'slug', '')) = 'english-vocabulary' order by p.created_at asc limit 1;
  if v_product_vocabulary is null then raise exception 'english-vocabulary product not found'; end if;

  -- immersion: a2-book-a-library-study-room (A2)
  if exists (select 1 from public.immersion_missions where product_id = v_product_immersion and language_id = v_en_id and slug = 'a2-book-a-library-study-room') then
    raise notice 'skipped existing immersion item %', 'a2-book-a-library-study-room';
  else
    insert into public.immersion_missions (slug, title, level, status, sort_order, metadata, context_text, objective_text, mission_type, target_vocabulary, target_grammar, cultural_note, success_conditions_json, skill_mix, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.context_text, r.objective_text, r.mission_type, r.target_vocabulary, r.target_grammar, r.cultural_note, r.success_conditions_json, r.skill_mix, v_product_immersion, v_en_id
    from jsonb_populate_record(null::public.immersion_missions, $seed${"slug":"a2-book-a-library-study-room","title":"Book a library study room","level":"A2","status":"published","sort_order":200,"metadata":{},"context_text":"You and two friends need a room to practise for a presentation. Check the library's rules and message your group.","objective_text":"Choose a time that works and explain how to keep the booking.","mission_type":"study","target_vocabulary":["booking","desk","available","cancel","library card"],"target_grammar":"Can for rules and requests. Before and after for times.","cultural_note":null,"success_conditions_json":["Choose a time that works and explain how to keep the booking.","Give the 4:30 time","Mention the library card","Say there are three people","Request the 4:30 slot"],"skill_mix":["reading","writing","speaking"]}$seed$::jsonb) r
    returning id into v_parent_id;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
