      jsonb_build_object('seeded_by', v_seed)
    from jsonb_populate_record(null::public.learning_content_registry_items, $seed${"service_key":"immersion","content_type":"immersion.mission","source_table":"immersion_missions","source_ref":"a2-book-a-library-study-room","title":"Book a library study room","skill_key":"immersion","cefr_level":"A2","difficulty":0.3,"status":"published","description":"Choose a time that works and explain how to keep the booking.","subskill_keys":["immersion.transfer","immersion.communication","immersion.problem-solving"],"estimated_minutes":10,"learning_objective":"Choose a time that works and explain how to keep the booking.","tags":["study","reading","writing","speaking"],"payload_json":{"mission_type":"study","skill_mix":["reading","writing","speaking"],"step_count":3,"format":"steps_v2"}}$seed$::jsonb) r
