    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Check the details","instructions":"Read the message and use its details to answer the questions.","prompt_text":"CYCLE WORKSHOP\nYour bicycle is ready. Collection on Friday is from noon to 6 pm. Saturday collection is before 11 am. Someone else can collect it for you with the repair number. Your number is 284. Please pay the 75,000 som balance at the counter.","expected_answer_json":{"questions":[{"id":"q1","prompt":"What does your brother need to collect the bicycle for you?","options":["Your old ticket for the bus","The bicycle's colour","Repair number 284"],"answer":2,"explanation":"The notice says a different person can collect it using the repair number, which is 284."},{"id":"q2","prompt":"Which time works if your brother can go only on Saturday?","options":["10:30 am","11:30 am","5:00 pm"],"answer":0,"explanation":"The Saturday window ends at 11 am. The Friday hours do not apply."}]},"target_skill_key":"reading.detail","estimated_minutes":3,"status":"published","metadata":{}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"writing","step_type":"reply","title":"Send the collection details","instructions":"Ask your brother to collect it on Saturday. Give him the number and confirm the amount to pay.","prompt_text":"Brother: I can go first thing on Saturday. What do I need?","expected_answer_json":{"goal":"Send the repair number and the balance.","points":[{"label":"Give repair number 284","any":["284","two eight four"]},{"label":"Give the 75,000 som balance","any":["75,000","75000","75 000","seventy-five thousand"]}],"model_answer":"Thanks! Can you get my bike before 11 on Saturday? The repair number is 284. There is 75,000 som to pay at the counter."},"target_skill_key":"writing.task_completion","estimated_minutes":4,"status":"published","metadata":{}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":2,"service_key":"speaking","step_type":"speak","title":"Check which brake was repaired","instructions":"You are at the counter. Give the repair number and ask whether the back brake was fixed.","prompt_text":"Mechanic: What can I do for you?","expected_answer_json":{"goal":"Identify the bicycle and check the completed work.","points":[{"label":"Identify the repair","any":["284","two eight four"]},{"label":"Ask about the back brake","any":["back brake","rear brake"]}],"model_answer":"I'm collecting the bike for repair number 284. Could you tell me if you fixed the back brake?"},"target_skill_key":"speaking.task_completion","estimated_minutes":3,"status":"published","metadata":{}}$seed$::jsonb) r;
