    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Check the details","instructions":"Read the message and use its details to answer the questions.","prompt_text":"SATURDAY BOOK EXCHANGE\nSet-up 09:00–10:00: label boxes and put signs outdoors. Desk 10:00–12:00: sign in donations. Pack-up 12:00–13:00: count leftover books and take boxes inside. For a swap, email the coordinator by Thursday afternoon with your replacement's name. Madina can only help at noon. You can arrive at 9:00 but must leave at 10:30.","expected_answer_json":{"questions":[{"id":"q1","prompt":"Which full shift could Madina take?","options":["Set-up","Pack-up","The donations desk"],"answer":1,"explanation":"Madina is available from noon. Pack-up starts at noon and lasts until 1 pm."},{"id":"q2","prompt":"What must the coordinator receive by Thursday afternoon?","options":["The name of the replacement","An estimate of leftover books","A copy of your exam schedule"],"answer":0,"explanation":"The instructions ask for an email with the replacement's name."}]},"target_skill_key":"reading.detail","estimated_minutes":3,"status":"published","metadata":{}}$seed$::jsonb) r;
