    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"writing","step_type":"reply","title":"Write to the coordinator","instructions":"Your original shift is pack-up. Request the swap and offer to cover the full set-up slot instead.","prompt_text":"Coordinator: Please email me your replacement's name and what you can cover.","expected_answer_json":{"goal":"Identify the replacement and offer the 9 am set-up slot.","points":[{"label":"Name Madina as your replacement","any":["Madina"]},{"label":"Offer set-up or the 9 am slot","any":["set-up","set up","9:00","9 am","nine"]}],"model_answer":"Hi Dilshod, could Madina cover my pack-up shift on Saturday? I need to leave by 10:30, but I can cover the complete 9:00–10:00 set-up slot. Would that work?"},"target_skill_key":"writing.task_completion","estimated_minutes":5,"status":"published","metadata":{}}$seed$::jsonb) r;
